@@ -113,11 +113,14 @@ function (vllm_finalize_hipify_target)
   list(REMOVE_DUPLICATES ALL_BYPRODUCTS)

   set(CSRC_BUILD_DIR ${CMAKE_CURRENT_BINARY_DIR}/csrc)
+  set(HIPIFY_MANIFEST ${CMAKE_CURRENT_BINARY_DIR}/hipify-source-map.json)
   add_custom_target(
     hipify_all
-    COMMAND ${Python_EXECUTABLE} ${CMAKE_SOURCE_DIR}/cmake/hipify.py -p ${CMAKE_SOURCE_DIR}/csrc -o ${CSRC_BUILD_DIR} ${ALL_SRCS}
+    COMMAND ${Python_EXECUTABLE} ${CMAKE_SOURCE_DIR}/cmake/hipify.py -p ${CMAKE_SOURCE_DIR}/csrc -o ${CSRC_BUILD_DIR} --manifest ${HIPIFY_MANIFEST} ${ALL_SRCS}
     DEPENDS ${CMAKE_SOURCE_DIR}/cmake/hipify.py ${ALL_SRCS}
-    BYPRODUCTS ${ALL_BYPRODUCTS}
+    BYPRODUCTS ${ALL_BYPRODUCTS} ${HIPIFY_MANIFEST}
+    WORKING_DIRECTORY ${CMAKE_SOURCE_DIR}
+    VERBATIM
     COMMENT "Running hipify on all extension source files.")
 endfunction()

@@ -25,6 +25,10 @@ variable "BUILDKITE_BUILD_ID" {
   default = ""
 }

+variable "VLLM_KERNEL_SYMBOL_MAP" {
+  default = "0"
+}
+
 variable "PARENT_COMMIT" {
   default = ""
 }
@@ -267,6 +271,8 @@ target "_ci-rocm" {
     CI_BASE_IMAGE         = CI_BASE_IMAGE
     ROCM_SMOKE_ID         = BUILDKITE_BUILD_ID
     max_jobs              = CI_MAX_JOBS
+    VLLM_KERNEL_SYMBOL_MAP = VLLM_KERNEL_SYMBOL_MAP
+    buildkite_commit      = BUILDKITE_COMMIT
   }
 }

@@ -302,6 +308,13 @@ target "csrc-rocm-ci" {
   output     = ["type=cacheonly"]
 }

+target "kernel-symbol-map-rocm" {
+  inherits   = ["_common-rocm", "_ci-rocm"]
+  target     = "kernel-symbol-map-rocm"
+  cache-from = get_cache_from_rocm_csrc()
+  output     = ["type=local,dest=./kernel-symbol-map-rocm"]
+}
+
 # Cache-only target for the Rust frontend build stage. Final-image cache
 # exports use mode=min and do not reliably persist intermediate cargo layers,
 # so Rust gets its own source-scoped cache target.
